# Encrypted assets only. The ASSET_KEY environment variable is required to decrypt them at runtime.
OFFICIAL_MASTER_ENC_B64 = """"""
GOLDEN_TEMPLATE_ENC_B64 = """"""

st.set_page_config(page_title="ANSARA FPL Ranking Extractor", page_icon="⚽", layout="centered")

# ---------------------------
# Security / asset loading
# ---------------------------
def require_password():
    expected = os.getenv("APP_PASSWORD", "").strip()
    if not expected:
        st.error("APP_PASSWORD is not configured on the server.")
        return False
    entered = st.text_input("Password", type="password")
    if not entered:
        st.info("Enter the app password.")
        return False
    if entered != expected:
        st.error("Incorrect password.")
        return False
    return True

@st.cache_resource
def load_assets():
    key = os.getenv("ASSET_KEY", "").strip()
    if not key:
        raise RuntimeError("ASSET_KEY is not configured on the server.")
    try:
        f = Fernet(key.encode("ascii"))
        master_token = base64.b64decode(OFFICIAL_MASTER_ENC_B64)
        template_token = base64.b64decode(GOLDEN_TEMPLATE_ENC_B64)
        master_bytes = f.decrypt(master_token)
        template_bytes = f.decrypt(template_token)
    except (ValueError, InvalidToken) as exc:
        raise RuntimeError("Unable to decrypt protected ranking assets. Check ASSET_KEY.") from exc
    master = json.loads(master_bytes.decode("utf-8"))
    return master, template_bytes

# ---------------------------
# FPL API
# ---------------------------
FPL_BASE = "https://fantasy.premierleague.com/api"
HEADERS = {"User-Agent": "ANSARA-FPL-Ranking-Extractor/1.0"}

def _fetch_one_history(entry_id, retries=3, timeout=25):
    url = f"{FPL_BASE}/entry/{entry_id}/history/"
    last_error = None
    for attempt in range(retries):
        try:
            r = requests.get(url, headers=HEADERS, timeout=timeout)
            r.raise_for_status()
            payload = r.json()
            current = payload.get("current", [])
            return entry_id, {int(x["event"]): int(x.get("points", 0) or 0) for x in current}
        except Exception as exc:
            last_error = exc
            if attempt < retries - 1:
                time.sleep(0.7 * (attempt + 1))
    raise RuntimeError(f"Entry {entry_id}: {last_error}")

def fetch_all_histories(entry_ids, workers=16, progress_callback=None):
    results = {}
    errors = []
    total = len(entry_ids)
    done = 0
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futures = {ex.submit(_fetch_one_history, eid): eid for eid in entry_ids}
        for fut in as_completed(futures):
            eid = futures[fut]
            try:
                key, history = fut.result()
                results[key] = history
            except Exception as exc:
                errors.append((eid, str(exc)))
            done += 1
            if progress_callback:
                progress_callback(done, total)
    if errors:
        sample = "; ".join(f"{eid}: {msg}" for eid, msg in errors[:10])
        raise RuntimeError(f"Failed to fetch {len(errors)} official entries. {sample}")
    return results

# ---------------------------
# Ranking engine
# ---------------------------
def competition_rank(sorted_values):
    ranks = []
    prev = object()
    current_rank = 0
    for i, v in enumerate(sorted_values, start=1):
        if i == 1 or v != prev:
            current_rank = i
            prev = v
        ranks.append(current_rank)
    return ranks

def build_rankings(master, score_history, selected_gw):
    participants = master["participants"]
    late_ids = set(master.get("late_from_gw2_entry_ids", []))
    eligible_chapters = master["eligible_group_chapters"]

    score_by_entry = {}
    for p in participants:
        eid = p["entry_id"]
        raw = score_history.get(eid, {})
        gw_scores = {}
        for gw in range(1, selected_gw + 1):
            val = int(raw.get(gw, 0) or 0)
            if gw == 1 and eid in late_ids:
                val = 0
            gw_scores[gw] = val
        score_by_entry[eid] = gw_scores

    indiv = []
    for p in participants:
        eid = p["entry_id"]
        total = sum(score_by_entry[eid].values())
        gw_score = score_by_entry[eid].get(selected_gw, 0)
        indiv.append({
            "entry_id": eid,
            "full_name": p["full_name"],
            "chapter": p["chapter"],
            "manager_name_fpl": p["manager_name_fpl"],
            "team_name_fpl": p["team_name_fpl"],
            "gw_score": gw_score,
            "total_score": total,
            "master_order": p["master_order"],
        })
    indiv.sort(key=lambda x: (-x["total_score"], x["master_order"]))
    ranks = competition_rank([x["total_score"] for x in indiv])
    individual_rows = []
    for rank, x in zip(ranks, indiv):
        individual_rows.append([
            rank, x["entry_id"], x["full_name"], x["chapter"],
            x["manager_name_fpl"], x["team_name_fpl"],
            x["gw_score"], x["total_score"]
        ])

    by_chapter = defaultdict(list)
    for p in participants:
        if p["chapter"] in eligible_chapters:
            by_chapter[p["chapter"]].append(p)

    group_stats = []
    for chapter in eligible_chapters:
        plist = by_chapter.get(chapter, [])
        weekly_totals = {}
        for gw in range(1, selected_gw + 1):
            ranked = sorted(
                plist,
                key=lambda p: (-score_by_entry[p["entry_id"]].get(gw, 0), p["master_order"]),
            )
            top5 = ranked[:5]
            weekly_totals[gw] = sum(score_by_entry[p["entry_id"]].get(gw, 0) for p in top5)
        group_stats.append({
            "chapter": chapter,
            "gw_score": weekly_totals.get(selected_gw, 0),
            "cumulative": sum(weekly_totals.values()),
        })

    group_stats.sort(key=lambda x: (-x["cumulative"], x["chapter"].casefold()))
    group_ranks = competition_rank([x["cumulative"] for x in group_stats])
    group_rows = []
    group_rank_by_chapter = {}
    for rank, x in zip(group_ranks, group_stats):
        group_rank_by_chapter[x["chapter"]] = rank
        group_rows.append([rank, x["chapter"], x["gw_score"], x["cumulative"]])

    detail_rows = []
    ordered_chapters = [x["chapter"] for x in group_stats]
    for chapter in ordered_chapters:
        plist = by_chapter.get(chapter, [])
        ranked = sorted(
            plist,
            key=lambda p: (-score_by_entry[p["entry_id"]].get(selected_gw, 0), p["master_order"]),
        )[:5]
        for pos, p in enumerate(ranked, start=1):
            detail_rows.append([
                group_rank_by_chapter[chapter], chapter, pos, p["entry_id"], p["full_name"],
                p["manager_name_fpl"], p["team_name_fpl"],
                score_by_entry[p["entry_id"]].get(selected_gw, 0),
            ])

    return individual_rows, group_rows, detail_rows

# ---------------------------
# Excel golden-template patching
# ---------------------------
NS_MAIN = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
NS_REL_DOC = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
NS_REL_PKG = "http://schemas.openxmlformats.org/package/2006/relationships"
NS_XML = "http://www.w3.org/XML/1998/namespace"
ET.register_namespace("", NS_MAIN)
ET.register_namespace("r", NS_REL_DOC)

def _sheet_paths(files):
    wb_root = ET.fromstring(files["xl/workbook.xml"])
    rel_root = ET.fromstring(files["xl/_rels/workbook.xml.rels"])
    rels = {r.attrib["Id"]: r.attrib["Target"] for r in rel_root.findall(f"{{{NS_REL_PKG}}}Relationship")}
    out = {}
    for s in wb_root.find(f"{{{NS_MAIN}}}sheets"):
        name = s.attrib["name"]
        rid = s.attrib[f"{{{NS_REL_DOC}}}id"]
        target = rels[rid].lstrip("/")
        if not target.startswith("xl/"):
            target = "xl/" + target
        out[name] = target
    return out

def _cell_row(ref):
    m = re.search(r"(\d+)$", ref)
    return int(m.group(1))

def _set_cell(root, ref, value):
    sheet_data = root.find(f"{{{NS_MAIN}}}sheetData")
    row_num = _cell_row(ref)
    row = None
    for r in sheet_data.findall(f"{{{NS_MAIN}}}row"):
        if int(r.attrib.get("r", 0)) == row_num:
            row = r
            break
    if row is None:
        raise KeyError(f"Missing template row {row_num}")

    cell = None
    for c in row.findall(f"{{{NS_MAIN}}}c"):
        if c.attrib.get("r") == ref:
            cell = c
            break
    if cell is None:
        raise KeyError(f"Missing template cell {ref}")

    for child in list(cell):
        cell.remove(child)

    if value is None:
        cell.attrib.pop("t", None)
        return

    if isinstance(value, bool):
        cell.attrib["t"] = "b"
        v = ET.SubElement(cell, f"{{{NS_MAIN}}}v")
        v.text = "1" if value else "0"
    elif isinstance(value, (int, float)) and not isinstance(value, bool):
        cell.attrib.pop("t", None)
        v = ET.SubElement(cell, f"{{{NS_MAIN}}}v")
        if isinstance(value, float) and value.is_integer():
            value = int(value)
        v.text = str(value)
    else:
        cell.attrib["t"] = "inlineStr"
        is_el = ET.SubElement(cell, f"{{{NS_MAIN}}}is")
        t = ET.SubElement(is_el, f"{{{NS_MAIN}}}t")
        text = str(value)
        if text.startswith(" ") or text.endswith(" ") or "\n" in text:
            t.attrib[f"{{{NS_XML}}}space"] = "preserve"
        t.text = text

def _patch_sheet(xml_bytes, updates):
    root = ET.fromstring(xml_bytes)
    for ref, value in updates.items():
        _set_cell(root, ref, value)
    return ET.tostring(root, encoding="utf-8", xml_declaration=True)

def generate_xlsx(template_bytes, gw, individual_rows, group_rows, detail_rows):
    zin = zipfile.ZipFile(io.BytesIO(template_bytes), "r")
    files = {name: zin.read(name) for name in zin.namelist()}
    zin.close()
    paths = _sheet_paths(files)

    indiv_updates = {"A1": f"ANSARA FPL ROAD TO KSA — INDIVIDUAL RANKING | GAMEWEEK {gw}", "G3": f"GW{gw} SCORE", "H3": "TOTAL SCORE"}
    for rnum, row in enumerate(individual_rows, start=4):
        for col, value in zip("ABCDEFGH", row):
            indiv_updates[f"{col}{rnum}"] = value

    group_updates = {"A1": f"ANSARA FPL ROAD TO KSA — GROUP RANKING | GAMEWEEK {gw}", "C3": f"GW{gw} SCORE", "D3": "CUMULATIVE GROUP SCORE"}
    for rnum, row in enumerate(group_rows, start=4):
        for col, value in zip("ABCD", row):
            group_updates[f"{col}{rnum}"] = value

    detail_updates = {"A1": f"ANSARA FPL ROAD TO KSA — TOP 5 CONTRIBUTORS BY CHAPTER | GAMEWEEK {gw}", "H3": f"GW{gw} SCORE"}
    for rnum, row in enumerate(detail_rows, start=4):
        for col, value in zip("ABCDEFGH", row):
            detail_updates[f"{col}{rnum}"] = value

    files[paths["INDIVIDUAL RANKING"]] = _patch_sheet(files[paths["INDIVIDUAL RANKING"]], indiv_updates)
    files[paths["GROUP RANKING"]] = _patch_sheet(files[paths["GROUP RANKING"]], group_updates)
    files[paths["GROUP RANKING DETAILS"]] = _patch_sheet(files[paths["GROUP RANKING DETAILS"]], detail_updates)

    out = io.BytesIO()
    with zipfile.ZipFile(out, "w", compression=zipfile.ZIP_DEFLATED) as zout:
        for name, content in files.items():
            zout.writestr(name, content)
    return out.getvalue()

# ---------------------------
# PDF generation (locked geometry)
# ---------------------------
HEADER_BLUE = "#1F4E78"

def _register_fonts():
    candidates = [
        ("/usr/share/fonts/truetype/croscore/Arimo-Regular.ttf", "/usr/share/fonts/truetype/croscore/Arimo-Bold.ttf"),
        ("/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf", "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf"),
    ]
    for reg, bold in candidates:
        if os.path.exists(reg) and os.path.exists(bold):
            try:
                pdfmetrics.registerFont(TTFont("ANSARA-Regular", reg))
                pdfmetrics.registerFont(TTFont("ANSARA-Bold", bold))
                return "ANSARA-Regular", "ANSARA-Bold"
            except Exception:
                pass
    return "Helvetica", "Helvetica-Bold"

REG_FONT, BOLD_FONT = _register_fonts()

def _fit_font(text, font_name, size, max_width, minimum=2.8):
    w = stringWidth(text, font_name, size)
    if w <= max_width or w == 0:
        return size
    return max(minimum, size * max_width / w)

def group_standings_pdf(gw, group_rows):
    data = [["RANK", "CHAPTER", f"GW{gw} SCORE", "CUMULATIVE GROUP SCORE"]] + group_rows
    out = io.BytesIO()
    c = canvas.Canvas(out, pagesize=letter)
    col_widths = [34.92, 152.64, 70.56, 158.40]
    x, y_top, row_h = 96.48, 724.32, 14.90625
    y = y_top
    for ri, row in enumerate(data):
        is_header = ri == 0
        if is_header:
            c.setFillColor(colors.HexColor(HEADER_BLUE))
            c.rect(x, y-row_h, sum(col_widths), row_h, stroke=0, fill=1)
        cx = x
        for val, cw in zip(row, col_widths):
            c.setStrokeColor(colors.black)
            c.setLineWidth(0.65)
            c.rect(cx, y-row_h, cw, row_h, stroke=1, fill=0)
            text = "" if val is None else str(val)
            fn = BOLD_FONT if is_header else REG_FONT
            fs = _fit_font(text, fn, 9.25, cw-3, 6.0)
            c.setFont(fn, fs)
            c.setFillColor(colors.white if is_header else colors.black)
            tx = cx + (cw - stringWidth(text, fn, fs))/2
            ty = y-row_h + (row_h-fs)*0.5 + 1.0
            c.drawString(tx, ty, text)
            cx += cw
        y -= row_h
    c.save()
    return out.getvalue()

def group_details_pdf(gw, detail_rows):
    header = ["GROUP RANK", "CHAPTER", "TOP 5 POSITION", "ENTRY ID", "FULL NAME", "MANAGER NAME FPL", "TEAM NAME FPL", f"GW{gw} SCORE"]
    pages = [detail_rows[:99], detail_rows[99:155]]
    y_tops = [731.52, 737.64]
    row_h = 6.73
    col_widths = [34.92, 68.76, 40.68, 24.12, 127.08, 73.44, 63.00, 31.68]
    x = 71.28

    out = io.BytesIO()
    c = canvas.Canvas(out, pagesize=letter)
    for page_idx, body_rows in enumerate(pages):
        include_header = page_idx == 0
        rows = ([header] if include_header else []) + body_rows
        y = y_tops[page_idx]
        for ri, row in enumerate(rows):
            is_header = include_header and ri == 0
            if is_header:
                c.setFillColor(colors.HexColor(HEADER_BLUE))
                c.rect(x, y-row_h, sum(col_widths), row_h, stroke=0, fill=1)
            cx = x
            for val, cw in zip(row, col_widths):
                c.setStrokeColor(colors.black)
                c.setLineWidth(0.35)
                c.rect(cx, y-row_h, cw, row_h, stroke=1, fill=0)
                text = "" if val is None else str(val)
                fn = BOLD_FONT if is_header else REG_FONT
                fs = 4.05 if is_header else 4.10
                fs = _fit_font(text, fn, fs, cw-2.0, 2.8)
                c.setFont(fn, fs)
                c.setFillColor(colors.white if is_header else colors.black)
                tx = cx + (cw - stringWidth(text, fn, fs))/2
                ty = y-row_h + (row_h-fs)*0.5 + 0.8
                c.drawString(tx, ty, text)
                cx += cw
            y -= row_h
        if page_idx < len(pages)-1:
            c.showPage()
    c.save()
    return out.getvalue()

# ---------------------------
# Streamlit UI
# ---------------------------
if not require_password():
    st.stop()

try:
    master, template_bytes = load_assets()
except Exception as exc:
    st.error(str(exc))
    st.stop()

st.title("ANSARA FPL Ranking Extractor")
st.caption(f"Official master: {master['official_manager_count']} managers • Group category: {len(master['eligible_group_chapters'])} chapters")
st.info("Uses the official ENTRY ID master directly, so outside league entries are ignored automatically.")

gw = st.selectbox("Gameweek", list(range(1, 39)), index=1)
if "outputs" not in st.session_state:
    st.session_state.outputs = None

if st.button("RUN EXTRACTOR", type="primary", use_container_width=True):
    entry_ids = [p["entry_id"] for p in master["participants"]]
    progress = st.progress(0, text="Fetching official FPL histories...")
    status = st.empty()

    def on_progress(done, total):
        progress.progress(done / total, text=f"Fetching FPL data: {done}/{total}")

    try:
        histories = fetch_all_histories(entry_ids, workers=16, progress_callback=on_progress)
        status.write("Calculating rankings...")
        individual_rows, group_rows, detail_rows = build_rankings(master, histories, gw)

        if len(individual_rows) != 803:
            raise RuntimeError(f"Safety check failed: expected 803 individual rows, got {len(individual_rows)}")
        if len(group_rows) != 31:
            raise RuntimeError(f"Safety check failed: expected 31 group rows, got {len(group_rows)}")
        if len(detail_rows) != 155:
            raise RuntimeError(f"Safety check failed: expected 155 detail rows, got {len(detail_rows)}")

        status.write("Generating Excel and PDFs...")
        xlsx_bytes = generate_xlsx(template_bytes, gw, individual_rows, group_rows, detail_rows)
        group_pdf = group_standings_pdf(gw, group_rows)
        details_pdf = group_details_pdf(gw, detail_rows)

        names = {
            "xlsx": f"ANSARA_FPL_OFFICIAL_RANKING_GW{gw}.xlsx",
            "group": f"GW{gw} GROUP STANDINGS.pdf",
            "details": f"GW{gw} GROUP STANDINGS DETAILS.pdf",
        }
        zbuf = io.BytesIO()
        with zipfile.ZipFile(zbuf, "w", compression=zipfile.ZIP_DEFLATED) as z:
            z.writestr(names["xlsx"], xlsx_bytes)
            z.writestr(names["group"], group_pdf)
            z.writestr(names["details"], details_pdf)

        st.session_state.outputs = {
            "gw": gw,
            "names": names,
            "xlsx": xlsx_bytes,
            "group": group_pdf,
            "details": details_pdf,
            "zip": zbuf.getvalue(),
        }
        progress.progress(1.0, text="Complete")
        status.success("Ranking files generated successfully.")
    except Exception as exc:
        progress.empty()
        status.empty()
        st.error(str(exc))

out = st.session_state.outputs
if out:
    st.subheader(f"Gameweek {out['gw']} files")
    st.download_button("Download Excel", data=out["xlsx"], file_name=out["names"]["xlsx"], mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", use_container_width=True)
    st.download_button("Download Group Standings PDF", data=out["group"], file_name=out["names"]["group"], mime="application/pdf", use_container_width=True)
    st.download_button("Download Group Details PDF", data=out["details"], file_name=out["names"]["details"], mime="application/pdf", use_container_width=True)
    st.download_button("Download All 3 Files (.zip)", data=out["zip"], file_name=f"ANSARA_FPL_GW{out['gw']}_FILES.zip", mime="application/zip", use_container_width=True)
